import React from 'react';

import ThreeDotsVertical from '@pohodnik/icons/svg/Controls/ThreeDotsVertical';
import clsx from 'clsx';
import { Link } from 'react-router-dom';

import { getWorkoutTypeColor } from '@apps/Workouts/@helpers/workouts.helper';
import { IWorkoutTarget, IWorkoutTargetStat } from '@apps/Workouts/@types/workoutsTargets.types';
import { dateRangeToLocaleString } from '@helpers/dateHelper';
import { declOfNum, formatAltitude, formatDistance } from '@helpers/formatHelper';
import PohAva from '@ui-kit/Ava';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import PohCard from '@ui-kit/Card';
import PohDropdown from '@ui-kit/Dropdown';

import WorkoutTargetProgress from './WorkoutTargetProgress';
import WorkoutTypeIcon from '../WorkoutTypeIcon';

interface IWorkoutTargetStatUserCardProps extends React.HTMLAttributes<HTMLDivElement> {
  workoutTargetStat: IWorkoutTargetStat;
  workoutTarget: IWorkoutTarget;
}

const WorkoutTargetStatUserCard: React.FC<IWorkoutTargetStatUserCardProps> = ({
  workoutTargetStat,
  workoutTarget,
  ...rest
}) => {
  return (
    <PohCard className="mb-4" {...rest}>
      <PohAva
        alt={[workoutTargetStat.user.name, workoutTargetStat.user.surname].join(' ')}
        className="me-2 float-start"
        src={workoutTargetStat.user.photo}
      />
      <div>
        {workoutTargetStat.statistic && (
          <PohDropdown
            className="float-end text-muted"
            menu={workoutTargetStat.statistic.workouts.map((wo) => (
              <Link
                key={wo.id}
                className="dropdown-item text-nowrap d-flex align-items-center"
                style={{ gap: 10 }}
                title={[
                  dateRangeToLocaleString(wo.date_start, wo.date_finish),
                  wo.type.name,
                  wo.name,
                ].join('\n')}
                to={`/workouts/${wo.id}`}
                target="_blank"
              >
                <span title={wo.type.name} style={{ color: getWorkoutTypeColor(wo.type.id) }}>
                  <WorkoutTypeIcon type={wo.type} />
                </span>
                <small className="text-truncate">{wo.name}</small>
                <PohBadge className="ms-auto" variant={BadgeVariant.Success}>
                  {formatDistance(wo.distance)}
                </PohBadge>
              </Link>
            ))}
          >
            <ThreeDotsVertical />
          </PohDropdown>
        )}
        <strong className={clsx(!workoutTargetStat && 'text-danger')}>
          {[workoutTargetStat.user.surname, workoutTargetStat.user.name].join('\u00a0')}{' '}
        </strong>
        &nbsp;
        {workoutTargetStat.statistic && (
          <sup
            title={workoutTargetStat.statistic.workouts
              ?.map((wo) =>
                [
                  `#${wo.id}`,
                  dateRangeToLocaleString(wo.date_start, wo.date_finish),
                  formatDistance(wo.distance),
                  wo.name,
                ].join('\t'),
              )
              .join('\n')}
          >
            <small className="text-muted">
              {workoutTargetStat.statistic.workouts.length}&thinsp;
              {declOfNum(workoutTargetStat.statistic.workouts.length, [
                'тренировка',
                'тренировки',
                'тренировок',
              ])}
            </small>
          </sup>
        )}
        <br />
        <small className={!workoutTargetStat.statistic ? 'text-warning' : 'text-success'}>
          {!workoutTargetStat.statistic
            ? `Подготовка не начата`
            : 'Тренируется c ' +
              workoutTargetStat.statistic.first_workout_date?.toLocaleDateString()}
        </small>
        <hr />
        {workoutTargetStat.statistic && (
          <>
            {workoutTarget.distance && workoutTarget.distance > 0 && (
              <WorkoutTargetProgress
                label="Расстояние"
                fromLabel={formatDistance(workoutTargetStat.statistic.distance || 0)}
                toLabel={formatDistance(workoutTarget.distance)}
                pct={
                  !workoutTargetStat
                    ? 0
                    : (workoutTargetStat.statistic.distance / workoutTarget.distance) * 100
                }
              />
            )}
            {workoutTarget.time_moving && workoutTarget.time_moving > 0 && (
              <WorkoutTargetProgress
                label="Время в движении"
                fromLabel={Math.round(
                  (workoutTargetStat.statistic.time_moving || 0) / 60 / 60,
                ).toString()}
                toLabel={Math.round(workoutTarget.time_moving / 60 / 60).toString() + '\u2009ч'}
                pct={
                  !workoutTargetStat
                    ? 0
                    : (workoutTargetStat.statistic.time_moving / workoutTarget.time_moving) * 100
                }
              />
            )}
            {workoutTarget.speed_avg && workoutTarget.speed_avg > 0 && (
              <WorkoutTargetProgress
                label="Средняя скорость"
                fromLabel={Math.round(workoutTargetStat.statistic.speed_avg || 0).toString()}
                toLabel={Math.round(workoutTarget.speed_avg).toString()}
                pct={
                  !workoutTargetStat
                    ? 0
                    : (workoutTargetStat.statistic.speed_avg / workoutTarget.speed_avg) * 100
                }
              />
            )}
            {workoutTarget.alt_ascent && workoutTarget.alt_ascent > 0 && (
              <WorkoutTargetProgress
                label="Набор высоты"
                fromLabel={formatAltitude(workoutTargetStat.statistic?.alt_ascent || 0)}
                toLabel={formatAltitude(workoutTarget.alt_ascent)}
                pct={
                  !workoutTargetStat
                    ? 0
                    : (workoutTargetStat.statistic.alt_ascent / workoutTarget.alt_ascent) * 100
                }
              />
            )}
            {workoutTarget.alt_descent && workoutTarget.alt_descent > 0 && (
              <WorkoutTargetProgress
                label="Сброс высоты"
                fromLabel={formatAltitude(workoutTargetStat?.statistic.alt_descent || 0)}
                toLabel={formatAltitude(workoutTarget.alt_descent)}
                pct={
                  !workoutTargetStat
                    ? 0
                    : (workoutTargetStat.statistic.alt_descent / workoutTarget.alt_descent) * 100
                }
              />
            )}
          </>
        )}
      </div>
    </PohCard>
  );
};

export default WorkoutTargetStatUserCard;
